#include "smartvehicle/platform/runtime.hpp"
#include <iostream>
using namespace smartvehicle;
int main(int argc,char**argv){auto config=load_config(argc>1?argv[1]:"config/profiles/host-simulation.json");if(!config){std::cerr<<"Configuration rejected: "<<config.detail<<'\n';return 2;}auto registry=std::make_shared<InProcessServiceRegistry>();auto events=std::make_shared<InProcessEventBus>();auto auth=std::make_shared<AllowListAuthorizer>(std::map<std::string,std::vector<std::string>>{{"vehicle-status",{"signals.read"}}});auto provider=std::make_shared<SimulatedSignalProvider>("simulator-a",std::map<std::string,SignalValue>{{"Vehicle.Speed",42.0},{"Vehicle.Powertrain.Battery.SoC",78.0},{"Vehicle.OperatingState",std::string("READY")}});VehicleSignalService service(provider,events,auth);registry->register_service({std::string(IVehicleSignalService::service_id),{1,0},"VehicleSignalService",{"signals.read"}});if(!registry->discover(IVehicleSignalService::service_id,{1,0}))return 3;auto token=events->subscribe("vehicle.signals",[](const VehicleSignal&s){std::cout<<"event="<<s.id<<" source="<<s.source<<" [SIMULATION]\n";},64);for(auto id:{"Vehicle.Speed","Vehicle.Powertrain.Battery.SoC","Vehicle.OperatingState"}){auto s=service.get("vehicle-status",id,std::chrono::milliseconds(100));if(!s)return 4;std::cout<<"signal="<<id<<" source="<<s.value->source<<" [SIMULATION]\n";service.sample_and_publish(id);}auto second=std::make_shared<SimulatedSignalProvider>("simulator-b",std::map<std::string,SignalValue>{{"Vehicle.Speed",7.0},{"Vehicle.Powertrain.Battery.SoC",61.0},{"Vehicle.OperatingState",std::string("PARKED")}});service.replace_provider(second);std::cout<<"provider-substitution="<<service.get("vehicle-status","Vehicle.Speed",std::chrono::milliseconds(100)).value->source<<" application-logic=unchanged\nhealth=healthy errors="<<service.health().error_count<<'\n';events->unsubscribe(*token.value);}
